/**
 * **XFormType & XFormSchema Reference**
 * 
 * `XFormSchema` is the foundational Zod schema that powers the VectorSigma dynamic rendering engine. 
 * Every form generated by `Teletraan1` adheres strictly to this schema definition. 
 * 
 * It enforces data integrity, handles automatic type coercion, and provides the blueprint for the deep-hydrated `XFormType` payload that gets submitted to your backend APIs.
 */
const meta: Meta = {
  title: 'χForm Components/XForm Schema Reference',
  parameters: {
    layout: 'padded',
    docs: {
      source: {
        code: `import { XFormSchema, type XFormType, type InputOption } from '@emeraldemperaur/vector-sigma';\n\n// Use XFormSchema for runtime validation\nconst parsed = XFormSchema.parse(rawJson);\n\n// Use XFormType for TypeScript definitions\nconst myForm: XFormType = { ... };`,
        language: 'tsx',
      },
    },
  },
  tags: ['autodocs'],
};

export default meta;
